set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
# Record the live bound I source before stopping only the authorized own job.
scontrol show job 2943 > "$R/runs/cosearch-local-gpu-five-20261003-i/cancel-allocation.txt"
"$R/env/bin/python" - <<'CHECK'
import subprocess
s=subprocess.check_output(['scontrol','show','job','2943'],text=True)
assert 'JobName=cosearch-local-five' in s and 'NodeList=h100-16' in s and 'JobState=RUNNING' in s
CHECK
"$R/env/bin/python" "$R/tools/capture_worker_i.py" > "$R/runs/cosearch-local-gpu-five-20261003-i/final-bound-capture.txt"
"$R/env/bin/python" - <<'RECORD'
import json,time
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/cosearch/runs/cosearch-local-gpu-five-20261003-i')
s=(r/'worker-training.log').read_text()
records=[]
for line in s.splitlines():
 if 'COSEARCH_OUTER_METRICS_JSON=' in line:records.append(json.JSONDecoder().raw_decode(line.split('COSEARCH_OUTER_METRICS_JSON=',1)[1])[0])
assert not records, 'I gained real updates: preserve/reassess before cancellation'
(r/'cancelled-for-speed.json').write_text(json.dumps(dict(job=2943,actual_outer_updates=0,accepted=False,time=time.time(),reason='Human-authorized rerun; single GPU first300 rank calls1214.57sec; stage reviewed eight-GPU implementation'))+'\n')
RECORD
scancel 2943
for attempt in $(seq 1 30); do
 if [ -z "$(squeue -h -j 2943 -o %i)" ]; then break; fi
 sleep 2
done
test -z "$(squeue -h -j 2943 -o %i)"
test -z "$(squeue -h --name=cosearch-local-five -o %i)"
base64 -d > "$R/tools/gpu-ranker-j.bundle" <<'BUNDLE'

BUNDLE
cd "$R/repo"
test "$(git rev-parse --short HEAD)" = 7bf802a
git fetch "$R/tools/gpu-ranker-j.bundle" HEAD
git merge --ff-only FETCH_HEAD
cp reproduction/baselines/agent6-20261002/local_gpu_five.py "$R/tools/five_iteration_job_j.py"
export OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 PYTHONPATH="$R/tools/test-lib:$R/repo"
"$R/env/bin/python" -m pytest tests/baselines -q > "$R/logs/gpu-ranker-j-native-cpu-tests.log" 2>&1
tail -2 "$R/logs/gpu-ranker-j-native-cpu-tests.log"
test ! -d "$R/runs/cosearch-local-gpu-five-20261003-j"
tmux new-session -d -s cosearch-local-gpu-five-j-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five env PYTHONPATH='$R/repo' COSEARCH_RUN_ID=cosearch-local-gpu-five-20261003-j '$R/env/bin/python' -m search_r1.baselines.preflight -- '$R/env/bin/python' '$R/tools/five_iteration_job_j.py' > '$R/logs/local-five-j.log' 2>&1"
sleep 3
squeue -h --name=cosearch-local-five -o '%i %T %N'
tail -5 "$R/logs/local-five-j.log"
